Done. We’re going to build this like **real machine interfaces**: tight enough to transmit power, chamfered enough to *never* seize.

Below is a **drop-in plugin + adapter spine** (Kotlin, Android-friendly) plus **4 starter plugins** (I Ching, Tarot Major, Runes, Numerology + an Elemental “thermal” read). It’s deterministic off `seed + dice`, and it bakes in your **tolerance mode** (Strict vs Forgiving) + **confidence band** (tight/medium/wide).

---

## 1) Core models + plugin protocol

Create: `halo/core/HaloModels.kt`

```kotlin
package halo.core

import kotlin.math.abs
import kotlin.math.ln

enum class ToleranceMode { STRICT, FORGIVING }
enum class ConfidenceBand { TIGHT, MEDIUM, WIDE }

data class DiceRoll(
    val sides: Int,
    val values: List<Int>,
) {
    init {
        require(sides >= 2) { "sides must be >= 2" }
        require(values.isNotEmpty()) { "values must not be empty" }
        require(values.all { it in 1..sides }) { "dice values must be in 1..sides" }
    }
}

data class OracleRequest(
    val question: String,
    val seed: Long,
    val dice: DiceRoll? = null,
    val tolerance: ToleranceMode = ToleranceMode.FORGIVING,
    val tags: Set<String> = emptySet(),
    val userId: String? = null,
    val timestampMs: Long = System.currentTimeMillis(),
)

data class Provenance(
    val method: String,
    val pluginId: String,
    val pluginVersion: String,
    val seed: Long,
    val usedDice: Boolean,
    val timestampMs: Long,
)

data class PluginSignal(
    val key: String,          // e.g., "action", "warning", "love", "structure"
    val weight: Double,       // 0..1-ish
    val text: String
)

data class PluginResult(
    val pluginId: String,
    val displayName: String,
    val confidence: ConfidenceBand,
    val summary: String,
    val details: String,
    val signals: List<PluginSignal>,
    val provenance: Provenance,
)

data class HaloSynthesis(
    val confidence: ConfidenceBand,
    val tolerance: ToleranceMode,
    val headline: String,
    val body: String,
    val mergedSignals: List<PluginSignal>,
)

data class HaloResponse(
    val request: OracleRequest,
    val results: List<PluginResult>,
    val synthesis: HaloSynthesis,
)

interface HaloPlugin {
    val id: String
    val version: String
    val displayName: String
    val method: String

    fun run(req: OracleRequest): PluginResult
}

/** Small util: stable pseudo-random from seed without java.util.Random. */
class SplitMix64(seed: Long) {
    private var x = seed
    fun nextLong(): Long {
        x += 0x9E3779B97F4A7C15L
        var z = x
        z = (z xor (z ushr 30)) * 0xBF58476D1CE4E5B9L
        z = (z xor (z ushr 27)) * 0x94D049BB133111EBL
        return z xor (z ushr 31)
    }
    fun nextInt(bound: Int): Int {
        require(bound > 0)
        val n = nextLong()
        val m = (n ushr 1) % bound.toLong()
        return m.toInt()
    }
    fun nextBoolean(): Boolean = (nextLong() and 1L) == 1L
}

/** Confidence derived from dice entropy-ish + question length; chamfered realism. */
fun estimateConfidence(req: OracleRequest): ConfidenceBand {
    val q = req.question.trim()
    val qLen = q.length.coerceAtLeast(1)
    val dice = req.dice

    // No dice? Medium by default (you can tighten later).
    if (dice == null) return if (qLen < 20) ConfidenceBand.MEDIUM else ConfidenceBand.WIDE

    val vals = dice.values
    val mean = vals.average()
    val varr = vals.map { (it - mean) * (it - mean) }.average()
    val stdev = kotlin.math.sqrt(varr)

    // Normalize stdev (roughly) against sides.
    val norm = stdev / (dice.sides / 2.0)
    return when {
        norm < 0.22 -> ConfidenceBand.TIGHT
        norm < 0.45 -> ConfidenceBand.MEDIUM
        else -> ConfidenceBand.WIDE
    }
}

/** Merge signals with tolerance (STRICT demands stronger consensus). */
fun synthesize(req: OracleRequest, results: List<PluginResult>): HaloSynthesis {
    val tol = req.tolerance
    val allSignals = results.flatMap { it.signals }

    // Group by key and sum weights
    val grouped = allSignals.groupBy { it.key }.mapValues { (_, sigs) ->
        sigs.sumOf { it.weight } to sigs
    }

    val threshold = when (tol) {
        ToleranceMode.STRICT -> 2.0   // needs more combined weight
        ToleranceMode.FORGIVING -> 1.0
    }

    val picked = grouped
        .filter { (k, v) -> v.first >= threshold }
        .toList()
        .sortedByDescending { it.second.first }
        .take(6)

    val mergedSignals = picked.flatMap { (_, pair) ->
        // choose top 1-2 texts per key (highest weight)
        pair.second.sortedByDescending { it.weight }.take(2)
    }

    val conf = results.map { it.confidence }.let { bands ->
        // Conservative: widest wins
        when {
            bands.any { it == ConfidenceBand.WIDE } -> ConfidenceBand.WIDE
            bands.any { it == ConfidenceBand.MEDIUM } -> ConfidenceBand.MEDIUM
            else -> ConfidenceBand.TIGHT
        }
    }

    val headline = when (tol) {
        ToleranceMode.STRICT -> "Tight coupling: follow the strongest lanes."
        ToleranceMode.FORGIVING -> "Chamfered coupling: integrate without grinding."
    }

    val body = buildString {
        appendLine("Top threads:")
        if (mergedSignals.isEmpty()) {
            appendLine("• No hard consensus — treat this as exploration, not marching orders.")
        } else {
            mergedSignals.forEach { s -> appendLine("• ${s.key}: ${s.text}") }
        }
        appendLine()
        appendLine("Confidence: $conf | Mode: $tol")
    }

    return HaloSynthesis(
        confidence = conf,
        tolerance = tol,
        headline = headline,
        body = body.trimEnd(),
        mergedSignals = mergedSignals
    )
}
