## 2) Adapters (the “gear tooth profiles”)

Create: `halo/core/HaloAdapters.kt`

```kotlin
package halo.core

object DiceAdapters {

    /** 6-bit line pattern for I Ching from dice; stable and simple. */
    fun toIChingIndex(req: OracleRequest): Int {
        val dice = req.dice ?: return (abs(req.seed) % 64).toInt()
        val bits = buildList {
            val src = dice.values
            // build 6 bits from dice values parity + seed jitter
            val rng = SplitMix64(req.seed xor src.sum().toLong())
            for (i in 0 until 6) {
                val v = src[i % src.size]
                val bit = ((v + rng.nextInt(2)) % 2) // 0 yin, 1 yang
                add(bit)
            }
        }
        // Convert bits to index 0..63
        var idx = 0
        for (b in bits) idx = (idx shl 1) or (b and 1)
        return idx and 63
    }

    /** Tarot Major Arcana index 0..21 + reversed flag. */
    fun toTarotMajor(req: OracleRequest): Pair<Int, Boolean> {
        val dice = req.dice
        val mix = (req.seed xor (dice?.values?.sum()?.toLong() ?: 0L))
        val rng = SplitMix64(mix)
        val idx = rng.nextInt(22)
        val reversed = rng.nextBoolean()
        return idx to reversed
    }

    /** Elder Futhark rune 0..23 + reversed flag. */
    fun toRune(req: OracleRequest): Pair<Int, Boolean> {
        val dice = req.dice
        val mix = (req.seed xor (dice?.values?.fold(0L) { a, v -> a * 31 + v } ?: 0L))
        val rng = SplitMix64(mix)
        val idx = rng.nextInt(24)
        val reversed = rng.nextBoolean()
        return idx to reversed
    }

    /** Simple “elements” from dice distribution across quartiles. */
    fun toElementBalance(req: OracleRequest): Map<String, Double> {
        val dice = req.dice ?: return mapOf("Fire" to 0.25, "Water" to 0.25, "Air" to 0.25, "Earth" to 0.25)
        val s = dice.sides.toDouble()
        val counts = mutableMapOf("Fire" to 0, "Water" to 0, "Air" to 0, "Earth" to 0)
        dice.values.forEach { v ->
            val p = v / s
            val key = when {
                p <= 0.25 -> "Earth"
                p <= 0.50 -> "Water"
                p <= 0.75 -> "Air"
                else -> "Fire"
            }
            counts[key] = (counts[key] ?: 0) + 1
        }
        val total = dice.values.size.toDouble()
        return counts.mapValues { it.value / total }
    }

    /** Numerology-ish: digital root of (letters+digits) value for question + dice sum. */
    fun toDigitalRoot(req: OracleRequest): Int {
        val base = req.question.filter { it.isLetterOrDigit() }.sumOf { it.code }
        val diceSum = req.dice?.values?.sum() ?: 0
        var n = base + diceSum
        fun dr(x: Int): Int {
            if (x == 0) return 0
            val r = x % 9
            return if (r == 0) 9 else r
        }
        return dr(abs(n))
    }
}
