## 3) Plugin registry + engine runner

Create: `halo/core/HaloEngine.kt`

```kotlin
package halo.core

class PluginRegistry {
    private val plugins = mutableListOf<HaloPlugin>()

    fun register(plugin: HaloPlugin): PluginRegistry = apply { plugins.add(plugin) }
    fun all(): List<HaloPlugin> = plugins.toList()
}

class HaloEngine(private val registry: PluginRegistry) {

    fun run(req: OracleRequest): HaloResponse {
        val results = registry.all().map { it.run(req) }
        val synthesis = synthesize(req, results)
        return HaloResponse(req, results, synthesis)
    }
}
```

