### I Ching plugin
Create: `halo/plugins/IChingPlugin.kt`

```kotlin
package halo.plugins

import halo.core.*

class IChingPlugin : HaloPlugin {
    override val id = "iching"
    override val version = "0.1.0"
    override val displayName = "I Ching (Hexagram)"
    override val method = "iching"

    // Names are public-domain-ish / traditional; short list is fine.
    private val hexNames = arrayOf(
        "Force", "Field", "Sprouting", "Enveloping", "Attending", "Arguing", "Army", "Holding Together",
        "Small Accumulating", "Treading", "Pervading", "Obstruction", "People in Harmony", "Great Possession",
        "Humbling", "Providing-For", "Following", "Correcting", "Nearing", "Viewing",
        "Gnawing Bite", "Grace", "Stripping Away", "Returning", "Without Embroiling", "Great Accumulating",
        "Swallowing", "Great Exceeding", "Gorge", "Radiance", "Conjoining", "Retiring",
        "Great Invigorating", "Prospering", "Darkening of the Light", "Dwelling People", "Polarising", "Limping",
        "Taking-Apart", "Diminishing", "Augmenting", "Parting", "Coupling", "Clustering",
        "Ascending", "Confining", "Welling", "Skinning", "Holding", "Shake",
        "Bound", "Infiltrating", "Converting the Maiden", "Abounding", "Sojourning", "Ground",
        "Open", "Dispersing", "Articulating", "Center Confirming", "Small Exceeding", "Already Fording", "Not Yet Fording",
        // pad to 64 if needed
    ).let { arr ->
        if (arr.size == 64) arr else Array(64) { i -> arr.getOrNull(i) ?: "Hexagram ${i + 1}" }
    }

    override fun run(req: OracleRequest): PluginResult {
        val idx = DiceAdapters.toIChingIndex(req)
        val conf = estimateConfidence(req)
        val name = hexNames[idx]
        val summary = "Hexagram ${idx + 1}: $name"

        val details = buildString {
            appendLine(summary)
            appendLine("Mode: ${req.tolerance} | Confidence: $conf")
            appendLine()
            appendLine("Reading (chamfered):")
            appendLine("• Look for the *stable* path that still has room to flex.")
            appendLine("• If something demands rigid obedience, treat it as misaligned teeth.")
            appendLine("• Commit to one clean move, then re-check the mesh.")
        }.trimEnd()

        val signals = listOf(
            PluginSignal("structure", 0.9, "Find the stable coupling before adding torque."),
            PluginSignal("timing", 0.7, "Small move → stabilize → next move."),
        )

        return PluginResult(
            pluginId = id,
            displayName = displayName,
            confidence = conf,
            summary = summary,
            details = details,
            signals = signals,
            provenance = Provenance(method, id, version, req.seed, req.dice != null, req.timestampMs)
        )
    }
}
