### Tarot (Major Arcana only, upright/reversed)
Create: `halo/plugins/TarotMajorPlugin.kt`

```kotlin
package halo.plugins

import halo.core.*

class TarotMajorPlugin : HaloPlugin {
    override val id = "tarot_major"
    override val version = "0.1.0"
    override val displayName = "Tarot (Major Arcana)"
    override val method = "tarot"

    private val majors = listOf(
        "The Fool","The Magician","The High Priestess","The Empress","The Emperor","The Hierophant",
        "The Lovers","The Chariot","Strength","The Hermit","Wheel of Fortune","Justice",
        "The Hanged Man","Death","Temperance","The Devil","The Tower","The Star","The Moon","The Sun",
        "Judgement","The World"
    )

    override fun run(req: OracleRequest): PluginResult {
        val (idx, rev) = DiceAdapters.toTarotMajor(req)
        val conf = estimateConfidence(req)
        val card = majors[idx]
        val orient = if (rev) "reversed" else "upright"
        val summary = "$card ($orient)"

        val details = buildString {
            appendLine(summary)
            appendLine("Mode: ${req.tolerance} | Confidence: $conf")
            appendLine()
            appendLine("Coupling note:")
            when (card) {
                "The Magician" -> appendLine("• Tools ready. Route power cleanly; don’t spray it everywhere.")
                "The Tower" -> appendLine("• If it won’t mesh, don’t force it—swap the adapter, not the whole engine.")
                "Temperance" -> appendLine("• Blend until it stabilizes. Chamfer the extremes.")
                else -> appendLine("• Treat this as a bias indicator: where the system wants to lean next.")
            }
            if (rev) appendLine("• Reversed = internalized / blocked / needs re-alignment before action.")
        }.trimEnd()

        val signals = mutableListOf<PluginSignal>()
        signals += PluginSignal("focus", 0.8, "Channel power through one clean interface.")
        if (rev) signals += PluginSignal("recalibrate", 0.8, "Fix alignment before applying torque.")

        return PluginResult(
            pluginId = id,
            displayName = displayName,
            confidence = conf,
            summary = summary,
            details = details,
            signals = signals,
            provenance = Provenance(method, id, version, req.seed, req.dice != null, req.timestampMs)
        )
    }
}
```

