### Numerology + Elemental “Thermal” plugin
Create: `halo/plugins/NumerologyElementalPlugin.kt`

```kotlin
package halo.plugins

import halo.core.*

class NumerologyElementalPlugin : HaloPlugin {
    override val id = "numerology_elemental"
    override val version = "0.1.0"
    override val displayName = "Numerology + Elements"
    override val method = "meta"

    override fun run(req: OracleRequest): PluginResult {
        val conf = estimateConfidence(req)
        val root = DiceAdapters.toDigitalRoot(req)
        val elems = DiceAdapters.toElementBalance(req)

        val topElem = elems.entries.maxByOrNull { it.value }?.key ?: "Earth"
        val summary = "Root $root + Elemental tilt: $topElem"

        val details = buildString {
            appendLine(summary)
            appendLine("Mode: ${req.tolerance} | Confidence: $conf")
            appendLine()
            appendLine("Digital root vibe:")
            appendLine("• $root = ${rootMeaning(root)}")
            appendLine()
            appendLine("Elemental balance:")
            elems.entries.sortedByDescending { it.value }.forEach {
                appendLine("• ${it.key}: ${(it.value * 100).toInt()}%")
            }
            appendLine()
            appendLine("Thermal rule:")
            appendLine("• If you feel “overclock heat,” don’t prove anything — just add coolant + reduce load.")
        }.trimEnd()

        val signals = listOf(
            PluginSignal("calibration", 0.9, "Adjust load to keep the system gliding."),
            PluginSignal("element", 0.6, "Lean into $topElem-style moves today.")
        )

        return PluginResult(
            pluginId = id,
            displayName = displayName,
            confidence = conf,
            summary = summary,
            details = details,
            signals = signals,
            provenance = Provenance(method, id, version, req.seed, req.dice != null, req.timestampMs)
        )
    }

    private fun rootMeaning(n: Int): String = when (n) {
        1 -> "Initiate. Cut a clean lane."
        2 -> "Pairing. Negotiate the interface."
        3 -> "Expression. Prototype out loud."
        4 -> "Structure. Build the bracket, then mount."
        5 -> "Change. Chamfer the edge—move fast without snapping."
        6 -> "Care. Stabilize the system and the people."
        7 -> "Insight. Observe, then strike once."
        8 -> "Power. Apply torque responsibly."
        9 -> "Completion. Close loops; ship the cycle."
        else -> "Neutral."
    }
}
